function Call-Tool([string]$name,[hashtable]$args){
  $r=Invoke-Rpc 'tools/call' @{name=$name;arguments=$args}
  if($r.error){ return @{ok=$false;err=($r.error|ConvertTo-Json -Compress)} }
  $txt=''
