  }

  if($Mode -eq 'full'){
    $s=Call-Tool 'dbx_open_session' @{connection_id=$conn;database='zentao';enable_transactions=$true}
    Write-Output ("open: "+$s.text)
    if(-not $s.ok){ throw 'open failed' }
    $sid=([regex]'session_id:\s*(\S+)' ).Match($s.text).Groups[1].Value
