  Write-Output ("FIXED_EXEC ok=$($r2.ok) : "+($r2.text -replace "`r?`n",' ').Substring(0,[Math]::Min(220,($r2.text -replace "`r?`n",' ').Length)))
  CT 'dbx_rollback_transaction' @{connection_id=$conn;session_id=$sid} | Out-Null
  CT 'dbx_close_session' @{connection_id=$conn;session_id=$sid} | Out-Null
}catch{ Write-Output ("ERR: "+$_.Exception.Message) }
finally{ try{$p.Kill()}catch{} }

param([Parameter(Mandatory=$true)][string]$Mode)
$ErrorActionPreference='Stop'
$exe='C:\Users\Administrator\.dbx\bin\dbx-mcp.exe'
$conn='4027e274-2f63-49e6-8a8d-5f25eb1e6c5e'
$plan='D:\plan\default-workspace'
$utf8=New-Object System.Text.UTF8Encoding($false)

$psi=New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName=$exe; $psi.UseShellExecute=$false
$psi.RedirectStandardInput=$true; $psi.RedirectStandardOutput=$true; $psi.RedirectStandardError=$true
$psi.StandardInputEncoding=$utf8; $psi.StandardOutputEncoding=$utf8
$p=[System.Diagnostics.Process]::Start($psi)
$script:seq=0
function Rpc([string]$method,[hashtable]$params,[bool]$notify=$false){
  $script:seq++; $id=$script:seq
  $m=@{jsonrpc='2.0';method=$method}; if(-not $notify){$m['id']=$id}; if($params){$m['params']=$params}
  $p.StandardInput.WriteLine(($m|ConvertTo-Json -Depth 16 -Compress)); $p.StandardInput.Flush()
  if($notify){return $null}
  while($true){
    $r=$p.StandardOutput.ReadLine()
    if($null -eq $r){throw "stdout closed waiting id=$id"}
    try{$o=$r|ConvertFrom-Json}catch{continue}
    if($o.id -eq $id){return $o}
  }
}
function CT([string]$name,[hashtable]$a){
  $r=Rpc 'tools/call' @{name=$name;arguments=$a}; $t=''
  if($r.error){return @{ok=$false;text=($r.error|ConvertTo-Json -Compress)}}
  if($r.result -and $r.result.content){foreach($c in $r.result.content){if($c.text){$t+=$c.text}}}
  $ie=$false; if($r.result -and $r.result.PSObject.Properties['isError']){$ie=[bool]$r.result.isError}
  return @{ok=(-not $ie);text=$t}
}
function Fix-Left([string]$s){ return $s.Replace(',left,', ','+[string][char]96+'left'+[string][char]96+',') }

try{
  Rpc 'initialize' @{protocolVersion='2024-11-05';capabilities=@{};clientInfo=@{name='d3';version='1'}} | Out-Null
  Rpc 'notifications/initialized' @{} $true | Out-Null
  $s=CT 'dbx_open_session' @{connection_id=$conn;database='zentao';enable_transactions=$true}
  if(-not $s.ok){throw 'open failed: '+$s.text}
  $script:sid=([regex]'(?m)^session_id:\s*(\S+)').Match($s.text).Groups[1].Value
  CT 'dbx_begin_transaction' @{connection_id=$conn;session_id=$script:sid} | Out-Null
  Write-Output ("SESSION "+$script:sid)

  if($Mode -eq 'probe4'){
    $l1=(Get-Content -LiteralPath (Join-Path $plan 'gen_tasks.sql') -Encoding UTF8 | Where-Object {$_.Trim() -ne ''} | Select-Object -First 1)
    $fx=Fix-Left $l1
    $r=CT 'dbx_execute_query' @{connection_id=$conn;session_id=$script:sid;sql=$fx}
    Write-Output ("CN_INSERT ok=$($r.ok) : "+($r.text -replace "`r?`n",' ').Substring(0,[Math]::Min(240,($r.text -replace "`r?`n",' ').Length)))
    CT 'dbx_rollback_transaction' @{connection_id=$conn;session_id=$script:sid} | Out-Null
    CT 'dbx_close_session' @{connection_id=$conn;session_id=$script:sid} | Out-Null
    exit 0
  }

  $total=0; $fail=$false
  foreach($f in @('gen_tasks.sql','gen_effort.sql')){
    $lines=Get-Content -LiteralPath (Join-Path $plan $f) -Encoding UTF8 | Where-Object {$_.Trim() -ne ''}
    Write-Output ("FILE $f stmts=$($lines.Count)")
    $idx=0
    foreach($line in $lines){
      $idx++
      $sql=Fix-Left $line
      $r=CT 'dbx_execute_query' @{connection_id=$conn;session_id=$script:sid;sql=$sql}
      if(-not $r.ok){ Write-Output ("FAIL $f#$idx : "+($r.text -replace "`r?`n",' ').Substring(0,[Math]::Min(300,($r.text -replace "`r?`n",' ').Length))); $fail=$true; break }
      $total++
      if($total % 20 -eq 0){ Write-Output ("progress total=$total ($f#$idx)") }
    }
    if($fail){break}
  }
  if($fail){throw 'stmt failed -> rollback'}
  Write-Output ("ALL_EXEC total=$total")

  foreach($q in @(
    "SELECT COUNT(*) AS n FROM zt_task WHERE id BETWEEN 2806 AND 2901",
    "SELECT COUNT(*) AS bad FROM zt_effort WHERE account='tiany' AND date>='2026-11-16' AND date<='2026-11-23' AND ROUND(consumed*10,0)<>consumed*10"
  )){
    $v=CT 'dbx_execute_query' @{connection_id=$conn;session_id=$script:sid;sql=$q;max_rows=5}
    Write-Output ("CHK: "+($v.text -replace "`r?`n",' '))
  }
  $c=CT 'dbx_commit_transaction' @{connection_id=$conn;session_id=$script:sid}
  Write-Output ("commit ok=$($c.ok) "+($c.text -replace "`r?`n",' '))
  if(-not $c.ok){throw 'commit failed'}
  CT 'dbx_close_session' @{connection_id=$conn;session_id=$script:sid} | Out-Null
  Write-Output "COMMIT_DONE"
  exit 0
}
catch{
  Write-Output ("CATCH: "+$_.Exception.Message)
  if($script:sid){try{$rb=CT 'dbx_rollback_transaction' @{connection_id=$conn;session_id=$script:sid};Write-Output ("ROLLBACK: "+($rb.text -replace "`r?`n",' '))}catch{};try{CT 'dbx_close_session' @{connection_id=$conn;session_id=$script:sid}|Out-Null}catch{}}
  exit 1
}
finally{ try{$p.Kill()}catch{} }
